LR = {
    "strong_for": 8.0,
    "weak_for": 1.5,
    "neutral": 1.0,
    "weak_against": 0.67,
    "strong_against": 0.125,
}
TEMPORAL_CAP = 1.5  # weak_for ceiling for temporal-only evidence


@dataclass
class BeliefUpdate:
