def close(self, hid: str, verdict: str, period: str) -> dict[str, Any] | None:
    kept = []
    closed = None
    for item in self.open_hypotheses:
        if item.get("id") == hid:
            closed = {**item, "verdict": verdict, "closed": period}
        else:
            kept.append(item)
    self.open_hypotheses = kept
    if closed:
        self.closed_hypotheses.append(closed)
    return closed

