def validate_text(text: str, node_values: dict[str, Any]) -> None:
    lowered = text.lower()
    for word in BANNED:
        if word in lowered:
            raise ValidationError(f"banned word '{word}' in output")
    allowed = flatten_values(node_values.values())
    missing = [
